// Walkthrough-video catalog for the public /videos pages and the pricing
// plans video. The data files are generated by scripts/generate-transcripts.mjs
// from the desktop repo (see CLAUDE.md "Embedding YouTube videos"); nothing here
// talks to YouTube at request time.
import { readFile } from "node:fs/promises";
import path from "node:path";
import {
  SITE_ORIGIN,
  embedUrl,
  isoDuration,
  videoObject,
  videoPageUrl,
  watchUrl,
} from "../../scripts/lib/video-jsonld.mjs";

export type CatalogVideo = {
  slug: string;
  videoId: string;
  title: string;
  description: string;
  seconds: number;
  publishedAt: string | null;
  group: string;
  tutorialSlugs: string[];
  featureSlug: string | null;
  featureRank?: number;
  pages: string[];
  thumbnailUrl: string;
  embedUrl: string;
  hasTranscript: boolean;
};

export type VideoCatalog = {
  generatedAt: string;
  groups: string[];
  videos: CatalogVideo[];
};

export type VideoTranscript = {
  title?: string;
  language?: string;
  paragraphs: { heading?: string; text: string }[];
};

const CONTENT_ROOT = path.join(process.cwd(), "content", "tutorials");

export async function loadVideoCatalog(): Promise<VideoCatalog> {
  try {
    const raw = await readFile(path.join(CONTENT_ROOT, "_video-catalog.json"), "utf8");
    const parsed = JSON.parse(raw) as Partial<VideoCatalog>;
    return {
      generatedAt: parsed.generatedAt || "",
      groups: Array.isArray(parsed.groups) ? parsed.groups : [],
      videos: Array.isArray(parsed.videos) ? parsed.videos : [],
    };
  } catch {
    return { generatedAt: "", groups: [], videos: [] };
  }
}

export async function loadVideoTranscripts(): Promise<Record<string, VideoTranscript>> {
  try {
    const raw = await readFile(path.join(CONTENT_ROOT, "_transcripts.json"), "utf8");
    const parsed = JSON.parse(raw) as { transcripts?: Record<string, VideoTranscript> };
    return parsed.transcripts && typeof parsed.transcripts === "object" ? parsed.transcripts : {};
  } catch {
    return {};
  }
}

export function findVideo(catalog: VideoCatalog, slug: string): CatalogVideo | null {
  if (!/^[a-z0-9][a-z0-9-]{0,80}$/i.test(slug)) return null;
  return catalog.videos.find((v) => v.slug === slug) || null;
}

export function groupVideos(catalog: VideoCatalog): { group: string; videos: CatalogVideo[] }[] {
  const order = [...catalog.groups, ...catalog.videos.map((v) => v.group)];
  const seen = new Set<string>();
  const out: { group: string; videos: CatalogVideo[] }[] = [];
  for (const g of order) {
    if (seen.has(g)) continue;
    seen.add(g);
    const videos = catalog.videos.filter((v) => v.group === g);
    if (videos.length) out.push({ group: g, videos });
  }
  return out;
}

/** "2:31" style label. */
export function formatDuration(seconds: number): string {
  const total = Math.max(0, Math.round(seconds || 0));
  const m = Math.floor(total / 60);
  const s = total % 60;
  return `${m}:${String(s).padStart(2, "0")}`;
}

export function totalMinutes(videos: CatalogVideo[]): number {
  return Math.round(videos.reduce((acc, v) => acc + (v.seconds || 0), 0) / 60);
}

export { SITE_ORIGIN, embedUrl, isoDuration, videoObject, videoPageUrl, watchUrl };
